mapper.select:
select a.PORTFOLIO_ID, a.FINPROD_ID, nvl(a.BUY_COST_AMT, 0) BUY_COST_AMT, nvl(a.SHARE_AMT, 0) SHARE_AMT, nvl(a.UNIT_COST, 0) UNIT_COST from PTL_SEC_UNITCOST a LEFT JOIN FIN_PRODUCT b ON a.FINPROD_ID =b.FINPROD_ID and b.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F01} LEFT JOIN FIN_PRODUCT_TYPE c ON a.FINPROD_ID =c.FINPROD_ID WHERE (( b.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F01} AND b.TRADE_MARKET=#{SVR_TRADE_MARKET_01} ) or (b.TRADE_MARKET in (#{SVR_TRADE_MARKET_03} ,#{SVR_TRADE_MARKET_04}))) AND a.CDATE=#{cdate}
AND a.PORTFOLIO_ID in
#{item}
ORDER BY a.PORTFOLIO_ID, a.FINPROD_ID

select
b.PORTFOLIO_ID ,
a.FINPROD_ID ,
a.PS ,
a.UNIT_CPRICE AS PRICE,
a.SHARE_AMT AS AMT
from TRD_PRODUCT_DEAL a
LEFT JOIN TRD_PRODUCT_DEAL_ADD b ON a.TRADE_ID =b.TRADE_ID
LEFT JOIN FIN_PRODUCT c ON a.FINPROD_ID =c.FINPROD_ID AND c.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F01}
LEFT JOIN FIN_PRODUCT_TYPE d ON d.FINPROD_ID =a.FINPROD_ID
WHERE a.TRADE_DATE =#{cdate} AND c.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F01} AND c.TRADE_MARKET=#{SVR_TRADE_MARKET_01}
AND a.PS IN (#{PS_T01},#{PS_T02},#{PS_T03}) AND a.TRADE_STATUS =#{TRADE_STATUS_01}
AND a.IS_CANCEL=#{YN_N}

    AND b.PORTFOLIO_ID in

        #{item}


ORDER BY b.PORTFOLIO_ID, a.FINPROD_ID , a.CREATE_TIME DESC

select b.PORTFOLIO_ID , a.FINPROD_ID , a.PS , a.UNIT_CPRICE AS PRICE, a.SHARE_AMT AS AMT from TRD_PRODUCT_DEAL a LEFT JOIN TRD_PRODUCT_DEAL_ADD b ON a.TRADE_ID =b.TRADE_ID LEFT JOIN FIN_PRODUCT c ON a.FINPROD_ID =c.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE d ON d.FINPROD_ID =a.FINPROD_ID WHERE a.TRADE_DATE =#{cdate} AND c.TRADE_MARKET in (#{SVR_TRADE_MARKET_03},#{SVR_TRADE_MARKET_04}) AND a.PS IN (#{PS_T01},#{PS_T02},#{PS_T03},#{PS_T04},#{PS_T49}) AND a.TRADE_STATUS =#{TRADE_STATUS_01} AND a.IS_CANCEL=#{YN_N}
AND b.PORTFOLIO_ID in
#{item}
ORDER BY b.PORTFOLIO_ID, a.FINPROD_ID , a.CREATE_TIME DESC
